import{_ as s,l as e,o as d,b as i,q as o,d as n,f as p,m as r}from"./chunks/framework.Tf23FRXt.js";const A=JSON.parse('{"title":"伊甸希望乐园 共鸣之章4","description":"","frontmatter":{},"headers":[{"level":2,"title":"P1","slug":"p1","link":"#p1","children":[]},{"level":2,"title":"P2","slug":"p2","link":"#p2","children":[]},{"level":2,"title":"P3","slug":"p3","link":"#p3","children":[]}],"relativePath":"duty/728.htm.md","filePath":"duty/728.md","lastUpdated":1791098838000}'),S={name:"duty/728.htm.md"};function a(k,t,u,O,B,T){const l=e("Role"),m=e("action");return d(),i("div",null,[t[15]||(t[15]=o('<h1 id="伊甸希望乐园-共鸣之章4" tabindex="-1">伊甸希望乐园 共鸣之章 4</h1><p>建议东西南北标 ABCD 辨别方向，场地边缘会掉下去，要注意。</p><h2 id="p1" tabindex="-1">P1</h2><p>BOSS 读条<mark>换装</mark>，有 2 种模式，但第一次必定是背对（需要背对的换装在 BOSS 头顶有红色眼睛标识，但是 BOSS 太高了经常有人看不见……）。实在懒得看就每次靠近 BOSS 并背对就可以。</p><p>镰形 / 阔斧回旋踢，镰形需要靠近，而阔斧需要远离 BOSS，这个技能最好看读条判断，看范围提示再跑通常来不及。</p><p>冰霜斩 / 刺，斩为背后安全，刺为左右前安全，同上最好记名字看读条。</p><p>核心技能：<mark>钻石星尘</mark>。被点名白色三角标记的玩家去场边找安全区放置 AOE，被点黄圈的人在中场适当互相远离即可。之后会有 4 人被点名追踪型 AOE，推荐互相远离到场边，并注意观察 AOE 提示并保持移动回避。</p><p>读条<mark>天降一击</mark>，有击退，可以用防击退技能处理，没技能的注意不要靠场边。</p><p>核心技能：<mark>镜中奇遇</mark>，场地上会出现镜子，镜子会复读 BOSS 的技能。第一次是冰霜斩 / 刺复读，如果是斩，则在 BOSS 身后躲完去南场（远离 2 个镜子）；如果是刺，则在 BOSS 正面躲完去北场（2 个镜子之间）。</p><h2 id="p2" tabindex="-1">P2</h2>',10)),n("p",null,[t[0]||(t[0]=p("小怪阶段。",-1)),t[1]||(t[1]=n("strong",null,"土元精",-1)),t[2]||(t[2]=p("会读条",-1)),t[3]||(t[3]=n("mark",null,"石肤",-1)),t[4]||(t[4]=p("，",-1)),r(l,{name:"tank"}),t[5]||(t[5]=p("T 注意使用",-1)),r(m,{name:"插言"}),t[6]||(t[6]=p("打断。",-1)),t[7]||(t[7]=n("strong",null,"雷元精",-1)),t[8]||(t[8]=p("会反伤，",-1)),r(l,{name:"healer"}),t[9]||(t[9]=p("治疗注意给队友抬血。",-1)),t[10]||(t[10]=n("strong",null,"水元精",-1)),t[11]||(t[11]=p("血厚，但可以被眩晕，",-1)),r(l,{name:"dps"}),t[12]||(t[12]=p("尽可能集火处理它。",-1))]),t[16]||(t[16]=o('<p>场边还有一个元精会连线，需要玩家截断连线。</p><p>包括连线在内，如果一共放跑 4 只小怪（小怪进入场地中央的水晶就算放跑），既告团灭。</p><h2 id="p3" tabindex="-1">P3</h2><p>BOSS 读条<mark>神圣</mark>的同时，头顶会有几个球，如果是 1 个球，就证明球砸中央，四周安全；如果是 4 个小球，那就是砸四周，中央安全。场地上特效也会发生变化。</p><p>核心技能：<mark>光之波动</mark>，场地上会依次出现 4、2、1 个塔，而且每次会有 2 名玩家被点名，被点名的玩家不可以踩塔，需要找没人的方向引导光波，剩下塔依次需要 1、2、4 人站进去处理。节奏较快，需要冷静处理。</p><p>核心技能：<mark>镜中奇遇</mark>，这次是镰形 / 阔斧复读，镰形先在 BOSS 脚下躲避，然后随便找个镜子底下躲避复读；阔斧需要先远离 BOSS 躲避，然后尽可能靠场地中央躲避复读。</p><p>最后一次场地结冰会配合闲寂 / 静寂的双剑技组合，是冰霜斩 / 刺的二连组合拳，如果控制不好的话可以考虑硬吃一个。</p>',7)),n("p",null,[t[13]||(t[13]=p("之后是多次 AOE，",-1)),r(l,{name:"healer"}),t[14]||(t[14]=p("治疗注意抬血。转场动画，站撸 rush 结束。",-1))])])}const f=s(S,[["render",a]]);export{A as __pageData,f as default};
